+        path.notes.push("threading: the passes did not lay as planned - no thread cycle record".into());
+        return;
+    };
+    let rec = ThreadCycle {
+        start: m0.to,
+        end: end.to,
+        major_diameter: 2.0 * ref_top,
+        minor_diameter: 2.0 * root,
+        lead: p.pitch,
+        height: ref_top - root,
+        first_depth,
+        min_depth: p.infeed.min(ref_top - root),
+        finish_allowance: 0.0,
+        infeed_angle: 0.0,
+        spring_passes: 0,
+        pull_out: 0.0,
+        first,
+        last,
+    };
